def _recorrer_al_cargar(nodo):
    """Recorre el arbol como ast.walk pero SIN entrar donde no corre al cargar.

    No entra en: el cuerpo de ast.Lambda (sus args tampoco; si sus defaults), el cuerpo de
    FunctionDef y AsyncFunctionDef anidadas (si sus decorator_list y defaults), ni el cuerpo
    de ClassDef anidadas (si sus bases, keywords y decorator_list). Asi no_carga no cuenta
    nombres leidos que solo corren cuando alguien llama a la funcion o crea el objeto.
    """
    pila = [nodo]
    while pila:
        actual = pila.pop()
        yield actual
        if isinstance(actual, ast.Lambda):
            for d in actual.args.defaults:
                pila.append(d)
            for d in actual.args.kw_defaults:
                if d is not None:
                    pila.append(d)
            continue
        if isinstance(actual, (ast.FunctionDef, ast.AsyncFunctionDef)):
            for d in actual.decorator_list:
                pila.append(d)
            for d in actual.args.defaults:
                pila.append(d)
            for d in actual.args.kw_defaults:
                if d is not None:
                    pila.append(d)
            continue
        if isinstance(actual, ast.ClassDef):
            for d in actual.decorator_list:
                pila.append(d)
            for b in actual.bases:
                pila.append(b)
            for k in actual.keywords:
                pila.append(k)
            continue
        for hijo in ast.iter_child_nodes(actual):
            pila.append(hijo)


